  "land.about": { en: "About", sw: "Kuhusu" },
  "land.heroTitle": { en: "SCHOOL MANAGEMENT SYSTEM", sw: "MFUMO WA USIMAMIZI WA SHULE" },
  "land.nowIs": { en: "NOW IS", sw: "SASA UKO" },
  "land.live": { en: "LIVE", sw: "HEWANI" },
  "land.explore": { en: "Explore Features", sw: "Angalia Huduma" },
  "feat.students.title": { en: "Student Management", sw: "Usimamizi wa Wanafunzi" },
  "feat.students.desc": { en: "Enroll and manage every student's record - personal details, class, stream and status - plus per-student charges, promotion between forms, and photo, PDF report and full history for every student, always in sync with Results, Hostel and Contributions.", sw: "Sajili na usimamie kumbukumbu za kila mwanafunzi - taarifa binafsi, darasa, mkondo na hali yake - pamoja na gharama za kila mwanafunzi, kupandishwa kidato, picha, ripoti ya PDF na historia kamili ya kila mwanafunzi, vyote vikiendana na Matokeo, Bweni na Michango." },
  "feat.results.title": { en: "Results Management", sw: "Usimamizi wa Matokeo" },
  "feat.results.desc": { en: "Teachers enter subject marks online; the system computes grades and Division automatically. The Academic Master reviews, unlocks or excludes a teacher's submission where needed, then compiles and publishes results as PDF or Excel. A dedicated Parents Reports section generates a Kiswahili Parent Report for every student with the Head Master's signature and school stamp applied automatically, and sends results to each parent by SMS.", sw: "Walimu huingiza alama za masomo mtandaoni; mfumo hukokotoa madaraja na Daraja la Ufaulu (Division) wenyewe. Mwalimu wa Taaluma hupitia, hufungua au huondoa alama za mwalimu inapohitajika, kisha huandaa na kuchapisha matokeo kama PDF au Excel. Sehemu maalum ya Ripoti za Wazazi hutengeneza Ripoti ya Mzazi kwa Kiswahili kwa kila mwanafunzi ikiwa na sahihi ya Mkuu wa Shule na muhuri wa shule, na hutuma matokeo kwa kila mzazi kwa SMS." },
  "feat.analytics.title": { en: "Analytics Dashboard", sw: "Takwimu na Uchambuzi" },
  "feat.analytics.desc": { en: "Turns years of results and attendance data into clear trend charts: school and per-subject pass-rate and GPA trends across exam periods, a school-wide teacher attendance trend over time, and an individual student's Division and GPA progress - each with an at-a-glance improving/declining/stable indicator.", sw: "Hubadilisha takwimu za miaka mingi za matokeo na mahudhurio kuwa michoro iliyo wazi: mwenendo wa ufaulu na GPA wa shule na wa kila somo katika vipindi vya mitihani, mwenendo wa mahudhurio ya walimu kwa shule nzima, na maendeleo ya Daraja la Ufaulu na GPA ya mwanafunzi mmoja - kila kimoja kikiwa na kiashiria cha kupanda/kushuka/kubaki palepale." },
  "feat.tams.title": { en: "TAMS (Teacher Attendance)", sw: "TAMS (Mahudhurio ya Walimu)" },
  "feat.tams.desc": { en: "Teachers check in each morning with GPS - the system verifies they're on the school compound and on time, flags late arrivals with a reason, and gives management a live daily and monthly attendance dashboard.", sw: "Walimu hujiandikisha kila asubuhi kwa GPS - mfumo huthibitisha kuwa wako ndani ya eneo la shule na wamefika kwa wakati, huonyesha waliochelewa pamoja na sababu, na huwapa viongozi dashibodi ya mahudhurio ya kila siku na ya kila mwezi." },
  "feat.timetable.title": { en: "Timetable Generator", sw: "Kutengeneza Ratiba" },
  "feat.timetable.desc": { en: "Assign teachers to subjects and classes, then auto-generate a clash-free timetable. View it per class, per teacher, or as one general school timetable, and export any view as PDF.", sw: "Wapangie walimu masomo na madarasa, kisha tengeneza ratiba isiyo na migongano yenyewe. Iangalie kwa kila darasa, kwa kila mwalimu, au kama ratiba moja ya shule nzima, na upakue mwonekano wowote kama PDF." },
  "feat.hostel.title": { en: "Hostel Management", sw: "Usimamizi wa Bweni" },
  "feat.hostel.desc": { en: "Admit boarding students into Boys or Girls hostel, manage rooms, record hostel contributions and discipline cases, and view each occupant's full history - with PDF exports throughout.", sw: "Wapokee wanafunzi wa bweni kwenye bweni la Wavulana au la Wasichana, simamia vyumba, rekodi michango ya bweni na kesi za nidhamu, na uone historia kamili ya kila mkazi - pamoja na kupakua PDF kila mahali." },
  "feat.contributions.title": { en: "Contributions Management", sw: "Usimamizi wa Michango" },
  "feat.contributions.desc": { en: "Track part-time student fees, Ream contributions and other school charges per term, with clear paid/outstanding status, printable receipts, and a history that both the office and each class teacher can review.", sw: "Fuatilia ada za wanafunzi wa muda, michango ya Rimu na gharama nyingine za shule kwa kila muhula, ukionyesha wazi kilicholipwa na kinachodaiwa, risiti za kuchapisha, na historia ambayo ofisi na kila mwalimu wa darasa wanaweza kuipitia." },
  "feat.food.title": { en: "Manage Foods", sw: "Usimamizi wa Chakula" },
  "feat.food.desc": { en: "The food teacher records each student's food contribution by type, with a running history and summary so the office can see who has contributed and who is still outstanding.", sw: "Mwalimu wa chakula hurekodi mchango wa chakula wa kila mwanafunzi kwa aina yake, pamoja na historia na muhtasari ili ofisi ione nani amechangia na nani bado anadaiwa." },
  "feat.communications.title": { en: "Communications", sw: "Mawasiliano" },
  "feat.communications.desc": { en: "Post school-wide announcements and send SMS updates to parents, staff, or any saved contact group via NextSMS - with delivery history kept for every message sent.", sw: "Weka matangazo ya shule nzima na tuma SMS kwa wazazi, walimu au kundi lolote la mawasiliano lililohifadhiwa kupitia NextSMS - historia ya kila ujumbe uliotumwa huhifadhiwa." },
  "feat.chatbot.title": { en: "Help Chatbot", sw: "Msaidizi wa Mfumo" },
  "feat.chatbot.desc": { en: "Stuck on a page or not sure how something works? Open the chat assistant in the corner of any screen and ask - it explains features and walks you through common tasks.", sw: "Umekwama kwenye ukurasa au huna uhakika jinsi kitu kinavyofanya kazi? Fungua msaidizi wa mazungumzo kwenye kona ya skrini yoyote na uulize - anaeleza vipengele na kukuongoza katika kazi za kawaida." },
