  "et.added": { en: "\"{name}\" has been added. Teachers can now choose it in Results Management.", sw: "\"{name}\" umeongezwa. Walimu sasa wanaweza kuuchagua kwenye Usimamizi wa Matokeo." },
  "et.updated": { en: "Exam type updated.", sw: "Mtihani umebadilishwa." },
