  "et.none": { en: "No exam types yet.", sw: "Bado hakuna aina za mitihani." },
  "et.lockedName": { en: "The exam type name cannot change because results already use it. Only the Kiswahili name can be changed.", sw: "Jina la mtihani haliwezi kubadilishwa kwa sababu tayari lina matokeo. Jina la Kiswahili pekee ndilo linaloweza kubadilishwa." },
