  "bk.whichTitle": { en: "Which one should I download?", sw: "Nipakue ipi?" },
  "bk.excelHelp": { en: "opens in Excel or Google Sheets. Each kind of record (students, staff, contributions, hostel, results…) is on its own sheet. Passwords and other secrets are not included.", sw: "inafunguka kwenye Excel au Google Sheets. Kila aina ya kumbukumbu (wanafunzi, walimu, michango, bweni, matokeo…) iko kwenye ukurasa wake. Manenosiri na siri nyingine hazimo." },
  "bk.fullHelp": { en: "the complete copy of the system. You cannot read it yourself; keep it safe (for example on a flash disk in the office). If the system ever loses its data, give this file to the system administrator to put everything back.", sw: "nakala kamili ya mfumo. Huwezi kuisoma mwenyewe; ihifadhi mahali salama (kwa mfano kwenye flash disk ofisini). Mfumo ukipoteza taarifa zake, mpe msimamizi wa mfumo faili hili ili arudishe kila kitu." },
  "bk.private": { en: "Both files contain private school records. Do not share them.", sw: "Faili zote mbili zina kumbukumbu za siri za shule. Usizishirikishe kwa mtu yeyote." },
  // ── Settings → SMS Gateway ──
  "smsgw.onlyManagers": { en: "This page is only available to Head Master, Second Master and Academic Master accounts.", sw: "Ukurasa huu ni kwa akaunti za Mkuu wa Shule, Makamu Mkuu wa Shule na Mwalimu wa Taaluma tu." },
  "smsgw.intro": { en: "Choose which service sends results by SMS (Results → Send Results via SMS). NextSMS is the school's paid service (billed per SMS). Android SMS Gateway sends from a phone the school owns, using its own SIM card.", sw: "Chagua huduma itakayotuma matokeo kwa SMS (Matokeo → Tuma Matokeo kwa SMS). NextSMS ni huduma ya kulipia ya shule (inalipiwa kwa kila SMS). Android SMS Gateway inatuma kutoka kwenye simu ya shule, kwa kutumia laini yake yenyewe." },
  "smsgw.saveConfirm": { en: "Save the SMS Gateway changes?", sw: "Hifadhi mabadiliko ya SMS Gateway?" },
  "smsgw.saved": { en: "SMS Gateway settings saved.", sw: "Mipangilio ya SMS Gateway imehifadhiwa." },
  "smsgw.provider": { en: "Service for sending results (Results SMS)", sw: "Huduma ya Kutuma Matokeo (SMS za Matokeo)" },
  "smsgw.androidHelp": { en: "In the \"SMS Gateway for Android\" app on the school phone: copy the URL, Username and Password shown there, then enter them here.", sw: "Kutoka programu ya \"SMS Gateway for Android\" kwenye simu ya shule: nakili URL, Username na Password vilivyoonyeshwa hapo, kisha viweke hapa." },
  "smsgw.url": { en: "Gateway address (URL)", sw: "Anwani ya Gateway (URL)" },
  "smsgw.pwSet": { en: "already set - leave empty to keep it", sw: "imeshawekwa - acha wazi kama hutaki kubadilisha" },
  // ── Settings → Signature & Stamp ──
  "sig.onlyRoles": { en: "This page is only available to the Head Master, Second Master, Academic Master and Class Teachers.", sw: "Ukurasa huu ni kwa Mkuu wa Shule, Makamu Mkuu wa Shule, Mwalimu wa Taaluma na Walimu wa Darasa tu." },
  "sig.intro": { en: "These images are placed automatically on every Parent Report PDF - nothing to do by hand each time a report is made.", sw: "Picha hizi huwekwa zenyewe kwenye kila Ripoti ya Mzazi (PDF) - hakuna cha kufanya kwa mkono kila ripoti inapotengenezwa." },
  "sig.photoTip": { en: "Take a clear photo of the signature or stamp on a plain sheet of paper. The white paper background is removed automatically, so it prints as if signed directly on the report.", sw: "Piga picha safi ya sahihi au muhuri kwenye karatasi nyeupe. Mandharinyuma ya karatasi huondolewa yenyewe, kwa hiyo inachapishwa kana kwamba imesainiwa moja kwa moja kwenye ripoti." },
  "sig.hmTitle": { en: "Head Master's Signature & School Stamp", sw: "Sahihi ya Mkuu wa Shule na Muhuri wa Shule" },
  "sig.hmSub": { en: "The School Stamp appears on every Parent Report (\"MHURI YA MKUU WA SHULE\" line). The Head Master's Signature is used on the Student Identity Card only - by policy it is never printed on Parent Reports.", sw: "Muhuri wa Shule unaonekana kwenye kila Ripoti ya Mzazi (mstari wa \"MHURI YA MKUU WA SHULE\"). Sahihi ya Mkuu wa Shule inatumika kwenye Kitambulisho cha Mwanafunzi tu - kwa sera ya shule haichapishwi kwenye Ripoti za Wazazi." },
  "sig.hmSignature": { en: "Head Master's Signature", sw: "Sahihi ya Mkuu wa Shule" },
  "sig.stamp": { en: "School Stamp", sw: "Muhuri wa Shule" },
  "sig.ctTitle": { en: "Class Teacher Signature", sw: "Sahihi ya Mwalimu wa Darasa" },
  "sig.ctSubAdmin": { en: "Used on the \"Sahihi\" line under the Class Teacher's comment. Choose a Form to upload or replace that class's Class Teacher's signature on their behalf.", sw: "Inatumika kwenye mstari wa \"Sahihi\" chini ya maoni ya Mwalimu wa Darasa. Chagua kidato ili kupakia au kubadilisha sahihi ya Mwalimu wa Darasa wa darasa hilo kwa niaba yake." },
  "sig.ctSubOwn": { en: "Used on the \"Sahihi\" line under your comment on your class's Parent Reports.", sw: "Inatumika kwenye mstari wa \"Sahihi\" chini ya maoni yako kwenye Ripoti za Wazazi za darasa lako." },
  "sig.form": { en: "Form", sw: "Kidato" },
  "sig.ctSignatureOf": { en: "{form} Class Teacher's Signature", sw: "Sahihi ya Mwalimu wa Darasa - {form}" },
  "sig.notCt": { en: "You are not currently assigned as Class Teacher of any Form, so there is no signature slot for you yet. Ask the Head Master, Second Master or Academic Master to assign you to a class.", sw: "Kwa sasa hujapangiwa kuwa Mwalimu wa Darasa wa kidato chochote, kwa hiyo bado huna nafasi ya sahihi. Mwombe Mkuu wa Shule, Makamu Mkuu wa Shule au Mwalimu wa Taaluma akupangie darasa." },
  "sig.yourSignature": { en: "Your Signature ({form} Class Teacher)", sw: "Sahihi Yako (Mwalimu wa Darasa - {form})" },
